  await page.goto('https://example.com');

  await expect(page).toHaveScreenshot({
    mask: [
      page.locator('.timestamp'),   // Mask timestamps
      page.locator('.user-count'),  // Mask dynamic counters
      page.locator('.advertisement') // Mask ads
